if (root == nullptr || child == nullptr) {
    return nullptr;
}

if (root == child) {
    return nullptr;
}

for (std::size_t i = 0; i < root->children.size(); i++) {
    if (root->children[i] == child) {
        return root;
    }

    Node* result = find_parent(root->children[i], child);
    if (result != nullptr) {
        return result;
    }
}

return nullptr;
